function showThankYouMessage() {
  // Display the thank-you message
const thankYouMessage = document.getElementById("thank-you");
thankYouMessage.style.display = "block"; // Make the message visible

setTimeout(function () {
  thankYouMessage.style.display = "none"; // Hide the message after 3 seconds
  $("#exampleModalCenter").modal("hide"); // Hide the modal if applicable
}, 3000);
}

$("#exampleModalCenter").on("hidden.bs.modal", function () {
completeForm(); // Call completeForm only after the modal is fully hidden
window.dataLayer = window.dataLayer || [];
window.dataLayer.push({
  event: "reach_out_modal_close",
  eventCategory: "User Interaction",
  eventAction: "Modal Close",
  eventLabel: "Strategic Assessment Modal"
});
});

document.addEventListener("DOMContentLoaded", function () {
const reachOutButtons = document.querySelectorAll("#reachout");
reachOutButtons.forEach(button => {
  button.addEventListener("click", function () {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
      event: "reach_out_click",
      eventCategory: "User Engagement",
      eventAction: "Modal Open",
      eventLabel: "Strategic Assessment Reach Out",
      buttonLocation: window.location.pathname
    });
  });
});

const reachoutForm = document.getElementById("reachoutForm");
if (reachoutForm) {
  reachoutForm.addEventListener("submit", function (event) {
    const nameInput = document.getElementById("Name");
    const emailInput = document.getElementById("Email");
    const orgInput = document.getElementById("Organisation");
    const describeInput = document.getElementById("Describe");
    const productInput = document.getElementById("Product");
    
    const validationErrors = [];
    if (!nameInput.value.trim()) validationErrors.push("name");
    if (!emailInput.value.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput.value.trim())) validationErrors.push("email");
    if (!orgInput.value.trim()) validationErrors.push("organisation");
    if (!describeInput.value.trim()) validationErrors.push("description");
    
    if (validationErrors.length > 0) {
      window.dataLayer.push({
        event: "reach_out_form_error",
        eventCategory: "Form Interaction",
        eventAction: "Validation Error",
        eventLabel: "Strategic Assessment Form",
        errorFields: validationErrors.join(",")
      });
      return;
    }
    
    window.dataLayer.push({
      event: "reach_out_form_submit",
      eventCategory: "Form Interaction",
      eventAction: "Form Submit",
      eventLabel: "Strategic Assessment Form",
      formData: {
        product: productInput.value,
        organization_provided: orgInput.value ? "yes" : "no"
      }
    });
  });
}
});

document
.getElementById("reachoutForm")
.addEventListener("submit", function (event) {
  event.preventDefault(); // Prevent default form submission
  const formData = new FormData(event.target);
  const submitButton = document.getElementById("reachoutformButton");
  const buttonText = submitButton.querySelector(".subscribe-button-text");

      // Change button text to "Submitting..."
  buttonText.textContent = "Submitting...";
  submitButton.disabled = true; // Disable the button to prevent multiple clicks

  fetch(
    "https://script.google.com/macros/s/AKfycbzz4tpv8cCk-Qcjivb7NpRwvArcyibfKHX0y5jiuPnuZz7DZasA2vtt2qtCsiGmftHI/exec",
    {
      method: "POST",
      body: formData,
    }
  )
    .then((response) => response.json())
    .then((data) => {
      // Display success response message
      document.getElementById("responseMessage").textContent =
        "Form submitted successfully!";
      showThankYouMessage(); // Show thank-you message
      buttonText.textContent = "Submitted";
    })
    .catch((error) => {
      // Handle errors
      document.getElementById("responseMessage").textContent =
        "An error occurred. Please try again.";
      console.error("Error:", error);
    });
});

function completeForm() {
// Reset all input fields
const form = document.getElementById("reachoutForm");
form.reset();
const submitButton = document.getElementById("reachoutformButton");
const buttonText = submitButton.querySelector(".subscribe-button-text");
buttonText.textContent = "Subscribe for updates"; // Reset button text
submitButton.disabled = false;
}
